INSERT INTO `jurnal_piket` VALUES (1,'2026-08-06',1,'Andi Wijaya, S.Pd','07:00 - 15:00','Kegiatan belajar mengajar berjalan kondusif. 2 siswa terlambat telah diberi pengarahan dan izin masuk kelas.','Kondusif',NULL,'2026-08-06 22:58:32','2026-08-06 22:58:32'),(2,'2026-08-05',1,'Rina Marlina, S.Pd','07:00 - 15:00','Penanganan siswa sakit di ruang UKS. Pembelajaran kelas X RPL 1 berjalan lancar.','Kondusif',NULL,'2026-08-06 22:58:32','2026-08-06 22:58:32'),(3,'2026-08-09',8,'Ruly Dwi Setyaningrum, S.Kom','07:00 - 15:00','Seluruh kegiatan belajar mengajar berjalan tertib. Presensi kehadiran guru dan siswa 98%.','Kondusif',NULL,'2026-08-09 08:36:54','2026-08-09 08:36:54'),(4,'2026-08-08',6,'Rifkotin Na\'imah, S.Pd','07:00 - 15:00','Penanganan 3 siswa terlambat jam pertama, telah diberikan pembinaan dan surat izin masuk kelas dari guru piket.','Ada Kejadian',NULL,'2026-08-09 08:36:54','2026-08-09 08:36:54'),(5,'2026-08-07',10,'Siswanti Purwaningsih, S.T., M.Pd','07:00 - 15:00','Pelaksanaan gladi bersih upacara bendera berjalan lancar. Satu siswa mengeluh pusing dan dirawat di UKS.','Lainnya',NULL,'2026-08-09 08:36:54','2026-08-09 08:36:54'),(6,'2026-08-04',2,'Rina Marlina, S.Pd','07:00 - 15:00','Suasana sekolah aman dan kondusif. Pengawasan jam istirahat dan perpustakaan berjalan tertib.','Kondusif',NULL,'2026-08-09 08:36:54','2026-08-09 08:36:54');
