INSERT INTO `pengumuman` VALUES (1,'Rapat Evaluasi Akhir Semester Genap','Rapat evaluasi untuk membahas hasil belajar dan kegiatan semester genap bagi seluruh staf pengajar.','Rapat',NULL,'07.00 - 08.30','aktif','-',1,'2026-06-05','2026-08-23 08:31:30','2026-08-29 02:02:32','2026-08-29 02:02:32',NULL),(2,'Workshop Kurikulum Merdeka','Workshop pengembangan kurikulum merdeka bagi seluruh guru produktif dan adaptif normatif.','Workshop',NULL,'08.00 - 09.30','aktif','Sakit',2,'2026-06-05','2026-08-23 08:31:30','2026-08-23 08:31:30',NULL,NULL),(3,'Pengumpulan RPP Semester Genap','Pengumpulan RPP untuk Semester Genap paling lambat tanggal 10 Juni 2026 di Sekretariat Kurikulum.','Kurikulum',NULL,'10.30 - 12.00','aktif','Urusan Keluarga',1,'2026-06-05','2026-08-23 08:31:30','2026-08-23 08:31:30',NULL,NULL),(4,'Perubahan Jadwal Mengajar','Terjadi perubahan jadwal mengajar untuk beberapa mata pelajaran kejuruan.','Perubahan Jadwal',NULL,'09.30 - 10.30','selesai','Oleh: Bagas P.',3,'2026-06-04','2026-08-23 08:31:30','2026-08-23 08:31:30',NULL,NULL),(5,'Pengumuman Penerima Tugas Tambahan','Daftar guru yang mendapatkan tugas tambahan semester genap dan pembimbing ekstrakurikuler.','Penugasan',NULL,'12.30 - 14.00','selesai','-',1,'2026-06-04','2026-08-23 08:31:30','2026-08-23 08:31:30',NULL,NULL),(6,'Sosialisasi Tata Tertib Sekolah','Sosialisasi tata tertib sekolah bagi seluruh guru, wali kelas, dan staf kependidikan.','Umum',NULL,'07.00 - 08.30','selesai','-',2,'2026-06-03','2026-08-23 08:31:30','2026-08-29 02:14:36','2026-08-29 02:14:36',2),(8,'MBG','segera ambil mbg pada saatnya','Umum',NULL,'7.30-8.00','aktif','MBG mendadak',44,'2026-08-27','2026-08-26 08:21:10','2026-08-29 02:13:44','2026-08-29 02:13:44',3),(9,'ada','v','Umum',NULL,'14:05 - 14:40','aktif','v',44,'2026-08-27','2026-08-26 10:21:48','2026-08-26 10:21:54','2026-08-26 10:21:54',NULL),(10,'Pemberitahuan Siswa Terlambat: Irfan Fani Setiawan (XI RPL 1)','PEMBERITAHUAN DARI GURU PIKET:\n\nSiswa berikut terlambat hadir di sekolah pada tanggal 28 August 2026 (Jam 08.00 WIB) dan sedang tidak mengikuti kegiatan belajar mengajar (KBM) tepat waktu:\n\n• NIS / NISN : 240134 / 0082075177\n• Nama Lengkap : Irfan Fani Setiawan\n• Kelas : XI RPL 1\n• Jenis Kelamin : Laki-laki\n• Waktu Terlambat : 08.00 WIB\n• Alasan Terlambat : Berak\n• Hukuman / Tindakan Piket : Nyapu Halaman\n\nPemberitahuan dari sistem web dan Guru Piket ini dikirimkan secara otomatis kepada Bapak/Ibu Guru Mengajar (Rina Marlina, S.Pd) agar Bapak/Ibu tidak mendata siswa sebagai alfa/bolos. Pengisian presensi siswa di jurnal mengajar tetap menjadi wewenang penuh Bapak/Ibu Guru Mengajar.','Siswa Telat',42,NULL,'aktif','Laporan Keterlambatan Siswa dari Petugas Piket (Petugas Piket)',130,'2026-08-28','2026-08-29 01:15:45','2026-08-29 01:16:36',NULL,NULL),(11,'MBG terbaru','MBG nya lebih banyak','Umum',2,'07.00 - 08.30','aktif','Siswa ambil MBG banyak',44,'2026-08-29','2026-08-29 01:43:34','2026-08-29 02:06:34','2026-08-29 02:06:34',NULL),(12,'Pemberitahuan Siswa Terlambat: Irfan Fani Setiawan (XI RPL 1)','PEMBERITAHUAN DARI GURU PIKET:\n\nSiswa berikut terlambat hadir di sekolah pada tanggal 27 August 2026 (Jam 07.30 WIB) dan sedang tidak mengikuti kegiatan belajar mengajar (KBM) tepat waktu:\n\n• NIS / NISN : 240134 / 0082075177\n• Nama Lengkap : Irfan Fani Setiawan\n• Kelas : XI RPL 1\n• Jenis Kelamin : Laki-laki\n• Waktu Terlambat : 07.30 WIB\n• Alasan Terlambat : Bangun Kesiangan\n• Hukuman / Tindakan Piket : Sapu Halaman Sekolah\n\nPemberitahuan dari sistem web dan Guru Piket ini dikirimkan secara otomatis kepada Bapak/Ibu Guru Mengajar (Umi Kulsum, S.Pd) agar Bapak/Ibu tidak mendata siswa sebagai alfa/bolos.','Siswa Telat',42,NULL,'aktif','Laporan Keterlambatan Siswa dari Petugas Piket (Petugas Piket)',118,'2026-08-27','2026-08-29 02:52:32','2026-08-29 02:53:06',NULL,NULL);
